 "content": "from collections import deque


def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            minr = min(y for y, x in cells)
            minc = min(x for y, x in cells)
            shape = frozenset((y - minr, x - minc) for y, x in cells)
            result.append((color, cells, shape))
    return result


def transform(grid):
    out = [row[:] for row in grid]
    objs = components(grid)
    # The lower-right 7 motif duplicates the lower 8 motif exactly; recolor
    # the duplicate to the motif's color.
    motifs8 = [shape for color, cells, shape in objs if color == 8]
    for color, cells, shape in objs:
        if color == 7 and shape in motifs8:
            for r, c in cells:
                out[r][c] = 8
    return out


if __name__ == '__main__':
    pass
